  "loc.gpsTracker": "🛰️ GPS-sporer",
  "loc.guide1": "Installer appen <b>«Traccar Client»</b> (App Store eller Google Play, gratis).",
  "loc.guide2": "I appen skriver du inn under <b>Device ID</b> (enhetsidentifikator):",
  "loc.guide3": "Skriv inn under <b>Server URL</b>:",
  "loc.guide4": "Nøyaktighet <b>Medium</b>, avstand <b>50 m</b>. Appen sender da bare når du beveger deg – ingenting når du står stille. Hvis du har flere felt (intervall, heartbeat), sett heartbeat til av eller 0.",
  "loc.guide5": "Tillat posisjonstilgang: <b>Alltid</b> og <b>Nøyaktig posisjon</b> på.",
  "loc.guide6": "Slå på <b>Service / Tracking</b>-bryteren, og <b>la den alltid stå på</b> – ferdig. Fra nå av styrer du alt i pinn.: «Send permanent» på eller av, «Send én gang» og SOS. Så lenge «Send permanent» er av, ser ingen posisjonen din, og pinn. registrerer ingen rute.",
  "loc.guideIntro": "Uten en annen app fungerer «📍 Del posisjon» direkte i pinn. – men bare mens pinn. er åpent. For at posisjonen også kommer fram når pinn. er lukket og skjermen er låst, sender den gratis appen «Traccar Client» den direkte til pinn. (ingen Traccar-server nødvendig). Samme for iPhone og Android.",
  "loc.h025013Watch5093": ", H02 5013, Watch 5093, Teltonika 5027. Denne porten må viderekobles til NAS-en i FRITZ!Box-en, fordi sporeren kobler til fra mobilnettet.",
