  "loc.setupIntro": "Telefoner trenger ingenting annet: Alle kan dele direkte i pinn. under «Min posisjon». I bakgrunnen (pinn. lukket) sender telefonen med den gratis appen «Traccar Client» (iPhone og Android) – direkte til pinn., ingen Traccar-server er nødvendig. Bare GPS-sporere med SIM-kort (f.eks. på et halsbånd) trenger containeren «traccar». Posisjonene blir på NAS-en din.",
