  "loc.traccarClientChooseSend": "I «Traccar Client» velger du «Send SOS» (avhengig av versjonen i appen eller ved å trykke og holde på app-ikonet). pinn. varsler umiddelbart alle i familien med push – med posisjon, adresse, tidspunkt og knapper for å ringe og nødnummer {regionNotrufText}. Tips: Skriv inn ditt eget mobilnummer i nødkortet.",
