  "settings.calendar.info": "Hver profil logger inn med sin egen iCloud- eller Google-konto og krysser av for kalenderne derfra: «For meg» ses bare av din egen profil, «Familie» ses og brukes av alle i familien din. De andre ser bare hvilken konto en familiekalender kommer fra – tilslørt, f.eks. m**l@g***l.com. Avtaler kan opprettes, redigeres, flyttes og settes i kø offline som vanlig og går direkte til iCloud eller Google (og dermed til telefonen). Synkronisering hvert 15. minutt eller med «Oppdater nå». Uten konto fungerer også en kalender bare på pinn.-serveren din. Påminnelser og dagssammendrag med push: private avtaler bare til deg.",
